receipt={'frozen_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'/root/judge_kasegi_round60','author_contract_commit':'eaf2ae1','files':{n:hashlib.sha256((p/n).read_bytes()).hexdigest() for n in ['challenge.json','private-oracle.json']},'isolation':'Oracle withheld procedurally on shared filesystem. No author answers read before freeze.'}
